-- ===== チャットボット（FAQ検索型）テーブル新設マイグレーション =====
-- 作成日：2026-07-28
-- 目的：docs/chatbot_faq_design.md で確定したFAQ検索型チャットボットのためのテーブルを新設する。
-- 実行方法：Supabase管理画面 → 左メニュー「SQL Editor」→「New query」→ 本ファイルの内容を
--          すべて貼り付けて「Run」を押す。上から順に実行されるため、そのまま一括実行してよい。
-- 再実行の安全性：create table if not exists・on conflict do nothingを使っているため、
--          誤って複数回実行しても壊れない（重複登録されない）。

-- ---------------------------------------------------------------------------
-- 1. faq_entries：チャットボットが検索して回答するFAQ本体
-- ---------------------------------------------------------------------------
create table if not exists public.faq_entries (
  id uuid primary key default gen_random_uuid(),
  major_category text not null,        -- 大カテゴリコード（例：'A'）
  major_label text not null,           -- 大カテゴリの表示名（例：'ログイン・パスワード・認証コード'）
  minor_category text not null unique, -- 中カテゴリコード（例：'A1'）。一意制約で二重登録を防ぐ
  question text not null,              -- 代表的な想定質問（検索対象・一覧表示用）
  keywords text not null default '',   -- 別の言い回し・口語表現（スペース区切り。検索時にquestionと合わせて照合）
  answer text not null,                -- 回答本文
  related_labels text not null default '', -- 関連する中カテゴリコード（カンマ区切り。例：'A2,A3'）
  escalation_note text not null default '', -- 「問い合わせへ誘導すべきケース」の説明（空なら常に自己解決可）
  sort_order int not null default 0,
  source text not null default 'initial' check (source in ('initial', 'user_submitted')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table public.faq_entries is 'チャットボットFAQ検索型の本体データ。管理部が新規追加・編集・削除する（RLSで管理部のみ書き込み可）。';

-- ---------------------------------------------------------------------------
-- 2. faq_inquiries：検索で見つからなかった質問（「質問を送る」フォームの記録）
-- ---------------------------------------------------------------------------
create table if not exists public.faq_inquiries (
  id uuid primary key default gen_random_uuid(),
  question_text text not null,
  submitted_by uuid not null references auth.users(id),
  submitted_by_email text,
  submitted_by_role text,
  submitted_at timestamptz not null default now(),
  status text not null default 'unanswered' check (status in ('unanswered', 'answered')),
  answer_text text,
  answered_by uuid references auth.users(id),
  answered_by_email text,
  answered_at timestamptz,
  created_faq_id uuid references public.faq_entries(id)
);

comment on table public.faq_inquiries is 'チャットボットで該当なしだった質問。管理部が回答すると faq_entries に新規登録され status が answered になる。';

create index if not exists faq_inquiries_status_idx on public.faq_inquiries (status, submitted_at desc);

-- ---------------------------------------------------------------------------
-- 3. RLS（Row Level Security）
-- ---------------------------------------------------------------------------
alter table public.faq_entries enable row level security;
alter table public.faq_inquiries enable row level security;

-- faq_entries：ログイン済みの社内ユーザー（担当営業／SSC／管理部）全員が閲覧可能
drop policy if exists faq_entries_select_authenticated on public.faq_entries;
create policy faq_entries_select_authenticated
  on public.faq_entries for select
  to authenticated
  using (true);

-- faq_entries：書き込み（追加・編集・削除）は管理部ロールのみ
-- current_role_name() は2026-07-15に作成済みのSECURITY DEFINER関数（staff_rolesからロールを引く）を再利用する。
drop policy if exists faq_entries_write_admin on public.faq_entries;
create policy faq_entries_write_admin
  on public.faq_entries for all
  to authenticated
  using (current_role_name() = '管理部')
  with check (current_role_name() = '管理部');

-- faq_inquiries：質問の送信は社内ユーザー全員が可能
drop policy if exists faq_inquiries_insert_authenticated on public.faq_inquiries;
create policy faq_inquiries_insert_authenticated
  on public.faq_inquiries for insert
  to authenticated
  with check (submitted_by = auth.uid());

-- faq_inquiries：閲覧は「自分が送った質問」または「管理部」のみ
drop policy if exists faq_inquiries_select_own_or_admin on public.faq_inquiries;
create policy faq_inquiries_select_own_or_admin
  on public.faq_inquiries for select
  to authenticated
  using (submitted_by = auth.uid() or current_role_name() = '管理部');

-- faq_inquiries：回答（更新）は管理部のみ
drop policy if exists faq_inquiries_update_admin on public.faq_inquiries;
create policy faq_inquiries_update_admin
  on public.faq_inquiries for update
  to authenticated
  using (current_role_name() = '管理部')
  with check (current_role_name() = '管理部');

